def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_bids = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) >= bid * 0.6:
                    dangerous_bids.append(float(bid))

    if not alive:
        safe_bid = min(budget, DAILY_SALARY * 0.25)
        if hp <= 2 or no_water_days >= 2:
            safe_bid = min(budget, DAILY_SALARY * 0.6)
        return max(0.0, float(safe_bid))

    high_pressure = max(prev_bids) if prev_bids else DAILY_SALARY * 0.6
    effective_pressure = max(dangerous_bids) if dangerous_bids else high_pressure

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.5
    elif hp <= 4:
        urgency += 0.3
    if no_water_days >= 2:
        urgency += 0.4
    elif no_water_days >= 1:
        urgency += 0.2
    if day >= 8:
        urgency += 0.1
    urgency += scarcity * 0.25
    if urgency > 1.0:
        urgency = 1.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(DAILY_SALARY * 0.9, effective_pressure + 2.0)
    elif scarcity >= 0.7:
        bid = max(DAILY_SALARY * 0.62, effective_pressure + 1.5)
    elif scarcity >= 0.4:
        bid = max(DAILY_SALARY * 0.48, effective_pressure * 0.72)
    else:
        bid = max(DAILY_SALARY * 0.28, effective_pressure * 0.5)

    if effective_pressure >= 120 and hp >= 5 and no_water_days == 0 and supply >= 20:
        bid = DAILY_SALARY * 0.22

    reserve_days = 3 if hp >= 4 else 2
    reserve = reserve_days * DAILY_SALARY
    affordable = budget - reserve
    if affordable < DAILY_SALARY * 0.2:
        affordable = budget * (0.55 + 0.35 * urgency)

    bid = min(bid, affordable)
    bid = min(bid, budget)

    floor_bid = 0.0
    if hp <= 3 or no_water_days >= 1:
        floor_bid = DAILY_SALARY * 0.35
    if scarcity >= 0.7:
        floor_bid = max(floor_bid, DAILY_SALARY * 0.42)
    if hp <= 2 or no_water_days >= 2:
        floor_bid = max(floor_bid, DAILY_SALARY * 0.75)

    bid = max(bid, floor_bid)
    bid = min(bid, budget)

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no one is alive, spend enough to ensure survival but not overspend
    if not alive_opps:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.45))

    # Read yesterday bids from previous_trace
    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Pressure signals from yesterday
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = (sum(yesterday_bids) / float(len(yesterday_bids))) if yesterday_bids else 0.0

    # Estimate how many full water units are realistically available today
    # (We don't know exact allocation rules; use supply to set aggressiveness.)
    supply_units = int(supply / WATER_REQ)  # safe int index usage; not used for indexing

    # Base bid: ensure we compete for at least one allocation when supply is constrained
    # Medium scenario: supply between 15 and 25 => 1 to 2 units.
    if supply < (MIN_SUPPLY + MAX_SUPPLY) / 2.0:
        base = DAILY_SALARY * 0.55
    else:
        base = DAILY_SALARY * 0.48

    # Escalation if yesterday saw very high bids (likely scarcity fight)
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_status['hp'] > 3:
            bid = DAILY_SALARY * 0.35
        else:
            bid = DAILY_SALARY * 0.85
    elif highest_prev_bid >= DAILY_SALARY * 0.65:
        # Moderate escalation
        bid = max(base, avg_prev_bid * 0.75)
    else:
        # If no extreme bidding, try to conserve budget
        bid = min(base, DAILY_SALARY * 0.52)

    # If our hp is low or we have many no-water days, increase to avoid death
    if my_status['hp'] <= 2:
        bid = max(bid, DAILY_SALARY * 0.9)
    elif my_status['no_water_days'] >= 2:
        bid = max(bid, DAILY_SALARY * 0.7)

    # If supply suggests only 1 unit, we should be a bit more competitive
    if supply_units <= 1:
        bid = max(bid, DAILY_SALARY * 0.6)

    # Budget cap
    bid = max(0.0, min(float(my_status['budget']), float(bid)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])  # ensure integer
    day = int(day_context['day'])
    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp_id, opp_data in alive_opponents.items():
        prev_trace = opp_data.get('previous_trace')
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(float(prev_trace['bid']))

    # Base bid calculation
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        # Estimate opponent aggressiveness; Cindy and David are high
        # If they bid very high yesterday, we must match or exceed
        if highest_prev >= DAILY_SALARY * 0.85:
            # High pressure scenario: bid just above highest if needed, else conserve
            if hp <= 2 or no_water_days > 0:
                bid = min(budget, highest_prev + 0.5)
            else:
                # We can afford to lose a round; bid slightly less
                bid = min(budget, DAILY_SALARY * 0.65)
        else:
            # Moderate pressure: outbid highest by small margin
            bid = min(budget, max(DAILY_SALARY * 0.6, highest_prev + 1.0))
    else:
        # No trace info: use conservative but safe bid
        if hp <= 2:
            bid = min(budget, DAILY_SALARY * 0.9)
        else:
            bid = min(budget, DAILY_SALARY * 0.55)

    # Adjust for low supply (high competition)
    if supply < 18:
        bid = min(budget, bid * 1.2)
    elif supply > 22:
        # Abundant supply, can lower a bit
        bid = min(budget, bid * 0.9)

    # Never bid more than budget
    bid = min(budget, max(0.0, bid))
    return bid
